import socket, struct
from concurrent.futures import ThreadPoolExecutor

def enc(name):
    return b''.join(bytes([len(l)]) + l.encode() for l in name.split('.')) + b'\x00'

def q(name, qtype=1, server='127.0.0.11'):
    pkt = struct.pack('>HHHHHH', 0x4321, 0x0100, 1, 0, 0, 0) + enc(name) + struct.pack('>HH', qtype, 1)
    s = socket.socket(socket.AF_INET, socket.SOCK_DGRAM); s.settimeout(2)
    try:
        s.sendto(pkt, (server, 53)); data,_ = s.recvfrom(4096)
    except Exception:
        return None
    finally:
        s.close()
    if (data[3] & 0xF) != 0:
        return None
    if struct.unpack('>H', data[6:8])[0] == 0:
        return None
    # crude A record parse
    an = struct.unpack('>H', data[6:8])[0]
    # skip question
    i = 12
    while data[i] != 0:
        i += data[i] + 1
    i += 5
    ips = []
    for _ in range(an):
        if data[i] & 0xC0 == 0xC0: i += 2
        else:
            while data[i] != 0: i += data[i] + 1
            i += 1
        t, c, ttl, rdl = struct.unpack('>HHIH', data[i:i+10]); i += 10
        if t == 1: ips.append('.'.join(str(b) for b in data[i:i+4]))
        i += rdl
    return ips

